import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def scope_nodes(doc, scope):
    node = node_by_title(doc, scope)
    if not node:
        return []
    return children(doc, node)

def table_rows(node):
    if not node or node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope) -> list:
    obj_node = node_by_title(doc, f"{scope}: Objects")
    if not obj_node:
        return []
    ents = []
    for line in obj_node["lines"]:
        # Example: "Object 0: green rubber cube (color=green, material=rubber, shape=cube)"
        match = re.match(r"Object (\d+): ([^\(]+)", line)
        if match:
            eid = f"Object {match.group(1)}"
            desc = match.group(2).strip()
            ents.append({"id": eid, "description": desc})
    return ents

def recorded_end(doc, scope) -> float or None:
    log_node = node_by_title(doc, f"{scope}: Motion log")
    if not log_node:
        return 127.0
    rows = table_rows(log_node)
    if not rows:
        return 127.0
    frames = [float(r["frame"]) for _, r in rows]
    return max(frames) if frames else 127.0

def inputs(doc, scope) -> list:
    event_node = node_by_title(doc, f"{scope}: Events")
    log_node = node_by_title(doc, f"{scope}: Motion log")
    if not event_node or not log_node:
        return []

    log_rows = table_rows(log_node)
    arrivals = []

    for i, line in enumerate(event_node["lines"]):
        # Format: "Frame 0: Object 0 (green rubber cube) is in view when the video begins."
        # Or: "Frame 10: Object 1 (red rubber sphere) enters the scene."
        match = re.match(r"Frame (\d+): Object (\d+) .* (?:is in view when the video begins|enters the scene)", line)
        if match:
            frame = float(match.group(1))
            obj_id_num = match.group(2)
            eid = f"Object {obj_id_num}"

            # Find corresponding state in motion log at this frame
            state_row = None
            state_idx = None
            for idx, row in log_rows:
                if float(row["frame"]) == frame and row["object"].startswith(obj_id_num + " "):
                    state_row = row
                    state_idx = idx
                    break

            fields = {}
            if state_row:
                for f_name in ["x", "y", "vx", "vy", "speed"]:
                    if f_name in state_row:
                        try:
                            fields[f_name] = float(state_row[f_name])
                        except (ValueError, TypeError):
                            pass

            srcs = [[event_node["node_id"], i]]
            if state_idx is not None:
                srcs.append([log_node["node_id"], state_idx])

            arrivals.append({
                "id": f"input_{eid}_{int(frame)}",
                "time": frame,
                "kind": "arrival",
                "entities": [eid],
                "fields": fields,
                "src": srcs
            })

    return arrivals

def outcomes(doc, scope) -> list:
    event_node = node_by_title(doc, f"{scope}: Events")
    if not event_node:
        return []

    outcomes_list = []
    for i, line in enumerate(event_node["lines"]):
        # Collisions: "Frame 12: Object 0 (green rubber cube) collides with Object 1 (brown rubber cylinder)."
        coll_match = re.match(r"Frame (\d+): Object (\d+).* collides with Object (\d+)", line)
        if coll_match:
            time = float(coll_match.group(1))
            eids = [f"Object {coll_match.group(2)}", f"Object {coll_match.group(3)}"]
            outcomes_list.append({
                "time": time,
                "kind": "collision",
                "entities": eids,
                "value": None,
                "src": [[event_node["node_id"], i]]
            })
            continue

        # Exits: "Frame 30: Object 0 (green rubber cube) exits the scene."
        exit_match = re.match(r"Frame (\d+): Object (\d+).* exits the scene", line)
        if exit_match:
            time = float(exit_match.group(1))
            eids = [f"Object {exit_match.group(2)}"]
            outcomes_list.append({
                "time": time,
                "kind": "exit",
                "entities": eids,
                "value": None,
                "src": [[event_node["node_id"], i]]
            })

    return outcomes_list

def params(doc, scope) -> dict:
    return {"stationary_threshold": 0.1}



