import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the physics process recorded in the scope.
    Objects slide on a flat floor and collide elastically.
    """
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # Entities that take part: those having at least one input.
    active_objects_ids = []
    for inp in inputs:
        for eid in inp["entities"]:
            if eid not in active_objects_ids:
                active_objects_ids.append(eid)

    # Motion log extraction for state initialization.
    log_node = node_by_title(doc, f"{scope}: Motion log")
    log_data = {}
    if log_node:
        rows = table_rows(log_node)
        for _, row in rows:
            # Object column format: '0 green rubber cube'
            obj_id = "Object " + row["object"].split(" ")[0]
            f = int(row["frame"])
            if obj_id not in log_data:
                log_data[obj_id] = {}
            log_data[obj_id][f] = {
                "x": float(row["x"]),
                "y": float(row["y"]),
                "vx": float(row["vx"]),
                "vy": float(row["vy"])
            }

    # Constants estimated from recorded data.
    # The velocity (vx, vy) is given as distance per second.
    # Displacement per frame is roughly 0.027 * velocity.
    FRAME_DURATION = 0.027 
    COLLISION_THRESHOLD = 0.42 # Mean observed collision distance is ~0.41-0.46
    BOUNDARY = 5.0

    # Initialize state at time 'start'
    state = {}
    for eid in active_objects_ids:
        # Object must have arrived by 'start' to be in state
        arrival = None
        for inp in inputs:
            if inp["entities"] == [eid] and inp["time"] <= start:
                if arrival is None or inp["time"] > arrival["time"]:
                    arrival = inp
        if arrival is None:
            continue

        # Initialize from most recent recorded state in motion log, projecting forward.
        latest_f = None
        if eid in log_data:
            for f in sorted(log_data[eid].keys()):
                if f <= start:
                    latest_f = f

        if latest_f is not None:
            s = log_data[eid][latest_f]
            dt = start - latest_f
            state[eid] = {
                "x": s["x"] + s["vx"] * FRAME_DURATION * dt,
                "y": s["y"] + s["vy"] * FRAME_DURATION * dt,
                "vx": s["vx"],
                "vy": s["vy"]
            }
        else:
            # Fallback to arrival input fields
            s = arrival["fields"]
            dt = start - arrival["time"]
            state[eid] = {
                "x": s["x"] + s["vx"] * FRAME_DURATION * dt,
                "y": s["y"] + s["vy"] * FRAME_DURATION * dt,
                "vx": s["vx"],
                "vy": s["vy"]
            }

    # Simulation loop
    outcomes_sim = []
    # Objects arriving after 'start'
    future_arrivals = sorted([inp for inp in inputs if inp["time"] > start], key=lambda x: x["time"])
    arrival_idx = 0
    t_curr = start
    dt = 1.0 # Step by 1 frame

    while t_curr < horizon:
        t_curr += dt
        t_frame = float(round(t_curr))

        # Process arrivals at this time step
        while arrival_idx < len(future_arrivals) and future_arrivals[arrival_idx]["time"] <= t_curr:
            inp = future_arrivals[arrival_idx]
            eid = inp["entities"][0]
            state[eid] = {
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"]
            }
            arrival_idx += 1

        # Update positions based on constant velocity
        for eid in list(state.keys()):
            state[eid]["x"] += state[eid]["vx"] * FRAME_DURATION * dt
            state[eid]["y"] += state[eid]["vy"] * FRAME_DURATION * dt

        # Check for collisions (Elastic, Equal Mass)
        eids = list(state.keys())
        for i in range(len(eids)):
            for j in range(i + 1, len(eids)):
                id1, id2 = eids[i], eids[j]
                p1 = np.array([state[id1]["x"], state[id1]["y"]])
                p2 = np.array([state[id2]["x"], state[id2]["y"]])
                v1 = np.array([state[id1]["vx"], state[id1]["vy"]])
                v2 = np.array([state[id2]["vx"], state[id2]["vy"]])

                dist = np.linalg.norm(p1 - p2)
                if dist <= COLLISION_THRESHOLD:
                    n = (p1 - p2) / (dist if dist > 0 else 1.0)
                    v_rel = v1 - v2
                    vn = np.dot(v_rel, n)
                    if vn < 0: # Only collide if moving towards each other
                        # Elastic collision physics for equal masses
                        state[id1]["vx"] -= vn * n[0]
                        state[id1]["vy"] -= vn * n[1]
                        state[id2]["vx"] += vn * n[0]
                        state[id2]["vy"] += vn * n[1]
                        outcomes_sim.append({
                            "time": t_frame,
                            "kind": "collision",
                            "entities": [id1, id2],
                            "value": None,
                            "src": []
                        })

        # Check for exits (Boundary defined as |x| > 5 or |y| > 5)
        for eid in list(state.keys()):
            if abs(state[eid]["x"]) > BOUNDARY or abs(state[eid]["y"]) > BOUNDARY:
                outcomes_sim.append({
                    "time": t_frame,
                    "kind": "exit",
                    "entities": [eid],
                    "value": None,
                    "src": []
                })
                del state[eid]

    # Return only outcomes that occur strictly after the provided start time
    return [o for o in outcomes_sim if o["time"] > start]

