        exit_match = re.match(r"Frame (\d+): (Object \d+) \(.*?\) exits the scene", line)

        if coll_match:
            outcomes_list.append({
                "time": float(coll_match.group(1)),
                "kind": "collision",
                "entities": [coll_match.group(2), coll_match.group(3)],
                "value": None,
                "src": [[ev_node['node_id'], i]]
            })
        elif exit_match:
            outcomes_list.append({
                "time": float(exit_match.group(1)),
                "kind": "exit",
                "entities": [exit_match.group(2)],
                "value": None,
                "src": [[ev_node['node_id'], i]]
            })

    return outcomes_list

